    }

    printf("Lector #%d leyo %d paginas en total.\n", contLector, totalLector);
    totalGeneral = totalGeneral + totalLector;
    contLector = contLector + 1;
}
printf("Total de paginas leidas por todos: %d\n", totalGeneral);
